  'gr.eyebrow': ['Greetings and names', 'పలకరింపులు, పేర్లు', 'ಶುಭಾಶಯಗಳು, ಹೆಸರುಗಳು', 'வாழ்த்துகள், பெயர்கள்'],
  'gr.h1': ['Say hello in Sanskrit.', 'సంస్కృతంలో పలకరించండి.', 'ಸಂಸ್ಕೃತದಲ್ಲಿ ಮಾತಾಡಿಸಿ.', 'சம்ஸ்கிருதத்தில் வணக்கம் சொல்லுங்கள்.'],
  'gr.p': ['Greetings, thank-yous and wishes you can use today, and Sanskrit names with what they mean. Tap share to send one as a card.', 'ఈరోజే వాడగలిగే పలకరింపులు, ధన్యవాదాలు, శుభాకాంక్షలు; అర్థాలతో సంస్కృత పేర్లు. కార్డుగా పంపడానికి షేర్ నొక్కండి.', 'ಇಂದೇ ಬಳಸಬಹುದಾದ ಶುಭಾಶಯಗಳು, ಧನ್ಯವಾದಗಳು; ಅರ್ಥದೊಂದಿಗೆ ಸಂಸ್ಕೃತ ಹೆಸರುಗಳು. ಕಾರ್ಡ್ ಆಗಿ ಕಳುಹಿಸಲು ಶೇರ್ ಒತ್ತಿ.', 'இன்றே பயன்படுத்தக்கூடிய வாழ்த்துகள், நன்றிகள்; பொருளுடன் சம்ஸ்கிருதப் பெயர்கள். அட்டையாக அனுப்ப பகிர் தொடுங்கள்.'],
  'gr.greetings': ['Greetings', 'పలకరింపులు', 'ಶುಭಾಶಯಗಳು', 'வாழ்த்துகள்'],
  'gr.names': ['Names and their meanings', 'పేర్లు, వాటి అర్థాలు', 'ಹೆಸರುಗಳು, ಅವುಗಳ ಅರ್ಥ', 'பெயர்களும் பொருளும்'],
